arguments.command:
cat << 'EOF' > test.dot
digraph G {
  rankdir=TB;
  newrank=true;
  splines=ortho;
  node[shape=box];

  subgraph cluster_dev { label="Dev"; dev_1; dev_2; }
  subgraph cluster_staging { label="Staging"; st_1; st_2; }

  dev_1 -> dev_2;
  dev_2 -> st_1;
  st_1 -> st_2;

  { rank=same; dev_1; st_1; }
}
EOF
dot -Tpng test.dot -o test.png
ls -la test.png

cat << 'EOF' > test2.dot
digraph G {
  rankdir=TB;
  newrank=true;
  splines=ortho;
  node[shape=box];

  subgraph cluster_dev { label="Dev"; dev_1; dev_2; dev_3; }
  subgraph cluster_staging { label="Staging"; st_1; st_2; }

  dev_1 -> dev_2;
  dev_2 -> dev_3;
  dev_3 -> st_1;
  st_1 -> st_2;
}
EOF
dot -Tpng test2.dot -o test2.png
