cat << 'EOF' > test3.dot
digraph G {
  rankdir=TB;
  newrank=true;
  splines=ortho;
  node[shape=box];

  subgraph cluster_dev { label="Dev"; dev_head [style=invis]; dev_1; dev_2; dev_3; dev_head -> dev_1 [style=invis]; }
  subgraph cluster_staging { label="Staging"; st_head [style=invis]; st_1; st_2; st_head -> st_1 [style=invis]; }

  { rank=same; dev_head; st_head; }

  dev_1 -> dev_2;
  dev_2 -> dev_3;
  dev_3 -> st_1;
  st_1 -> st_2;
}
EOF
dot -Tpng test3.dot -o test3.png
ls -la test3.png
